(6559053, 976966, 108580, '<td valign="top">Easily a <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_N.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_N.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_N.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=96751" rel="nofollow" target="_blank">Tanguera</a> shot. Classy. Emotive. Thought provoking.</td>', 'Easily a  Tanguera shot. Classy. Emotive. Thought provoking.', '2011-10-03 07:54:45.000000', NULL, 1),
(6559054, 976306, 108580, '<td valign="top">Fabulous idea and good execution. I think you will be unhappy with the processing. The black velvet cloth needs to be so much darker to make the balls stand out accentuating their geometric movement and trail. As difficult as this was to shoot, I''d be giving it +1 if a ball sunk on the break :)</td>', 'Fabulous idea and good execution. I think you will be unhappy with the processing. The black velvet cloth needs to be so much darker to make the balls stand out accentuating their geometric movement and trail. As difficult as this was to shoot, I''d be giving it +1 if a ball sunk on the break :)', '2011-10-03 07:57:09.000000', NULL, 1),
